using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AustraCharacterAchievement", menuName = "Data/Characters/AustraCharacterAchievement")]
public class AustraCharacterAchievement : CharacterAchievement
{
	[SerializeField]
	private CriticalTwistAchievementData criticalTwistAchievementData;

	public override void OnUnitPurified(int purifyAmount, GameObject source)
	{
		criticalTwistAchievementData.CriticalTwistUnlock(purifyAmount, source);
	}
}
